import heapq

def shortest_path(edges, start, end):
    # Handle case where start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list from edges
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = {}
        graph[from_node][to_node] = weight

    # Check for negative edge weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed")

    # If either start or end node doesn't appear in the graph, return None path
    if start not in graph:
        return (None, None)

    # Use a set of reachable nodes for validation of 'end'
    reachable_nodes = set()
    for from_node in graph:
        reachable_nodes.add(from_node)
        reachable_nodes.update(graph[from_node].keys())

    if end not in reachable_nodes:
        return (None, None)

    # Initialize Dijkstra's algorithm
    distances = {node: float('inf') for node in reachable_nodes}
    distances[start] = 0
    previous = {node: None for node in reachable_nodes}

    priority_queue = [(0, start)]
    visited = set()

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # Skip if already visited
        if current_node in visited:
            continue

        visited.add(current_node)

        # If we've reached the target node, stop early
        if current_node == end:
            break

        # Explore neighbors if they exist
        if current_node in graph:
            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight
                if not (neighbor in visited) and distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(priority_queue, (distance, neighbor))

    # Check if path exists to end node
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct the path from end to start
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous[current]

    path.reverse()

    return (distances[end], path)
